"""Bind manually reviewed F401 routed gate/pins to matched controls."""
import datetime,hashlib,json
from pathlib import Path
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
ip=Path('outerreset-f401-inspection.json');r=json.loads(ip.read_text());assert r['phase']=='fresh_netlist_inspected_manual_configuration_required' and r['actual_exit_code']==0
text=Path(r['inspection_text']);assert sha(text)==r['inspection_text_sha256'];s=text.read_text()
for phrase in ['CELL u_KeepPwrOnRst/reset_sync1_i_1 REF LUT3','INIT 8\'hBA','PIN I0 DRIVERS u_KeepPwrOnRst/reg_reset_reg/Q','PIN I1 DRIVERS u_PcsWait/reg_reset_reg/Q','PIN I2 DRIVERS u_PcsWaitEnd/reg_reset_reg/Q','CLOCKS clk_sys','pma_reset_pipe_reg[3]/PRE']:assert phrase in s,phrase
gate='u_KeepPwrOnRst/reset_sync1_i_1';clockdriver='u_ClkMan_Inst/inst/clkout1_buf/O';timers=['u_KeepPwrOnRst/reg_reset_reg/C','u_PcsWait/reg_reset_reg/C','u_PcsWaitEnd/reg_reset_reg/C']
out=Path('outerreset-f401-netlist-config.json');tcl=Path('outerreset-f401-netlist-config.tcl');assert not out.exists() and not tcl.exists()
data="""set cfg [dict create candidate f401 dcp {lrtdc-outerreset-f401/build/outerreset-f401/lrtdc-outerreset-f401.dcp} root {outerreset-f401-matched} gate {u_KeepPwrOnRst/reset_sync1_i_1} reference LUT3 enabled_init {8'hBA} variants {enabled 8'hBA bypass 8'hAA hold 8'hF0} drivers {I0 {u_KeepPwrOnRst/reg_reset_reg/Q} I1 {u_PcsWait/reg_reset_reg/Q} I2 {u_PcsWaitEnd/reg_reset_reg/Q}} timer_clocks {u_KeepPwrOnRst/reg_reset_reg/C 8.000 u_PcsWait/reg_reset_reg/C 8.000 u_PcsWaitEnd/reg_reset_reg/C 8.000} timer_drivers {u_KeepPwrOnRst/reg_reset_reg/C {u_ClkMan_Inst/inst/clkout1_buf/O} u_PcsWait/reg_reset_reg/C {u_ClkMan_Inst/inst/clkout1_buf/O} u_PcsWaitEnd/reg_reset_reg/C {u_ClkMan_Inst/inst/clkout1_buf/O}}]
"""
tcl.write_text(data)
cfg={'created':datetime.datetime.now().isoformat(),'phase':'fresh_netlist_configuration_reviewed','candidate':'f401','dcp':'lrtdc-outerreset-f401/build/outerreset-f401/lrtdc-outerreset-f401.dcp','root':'outerreset-f401-matched','gate':gate,'reference':'LUT3','enabled_init':"8'hBA",'input_roles':{'I0':'por','I1':'wait','I2':'end'},'input_inversions':{'I0':False,'I1':False,'I2':False},'variant_inits_decimal':{'enabled':186,'bypass':170,'hold':240},'timer_clocks':{pin:{'period_ns':8.,'clock':'clk_sys','driver':clockdriver} for pin in timers},'source_sha256':{str(p):sha(p) for p in [Path(__file__),ip,text,tcl]},'limits':['Fresh gate is physically named under u_KeepPwrOnRst by synthesis, but its output drives only the public PCS reset sinks listed in inspection.','All three INIT truth tables are recomputed independently by the review before hardware. Hold extends initial public reset continuously; enabled creates a reset-free gap and a second pulse.','Only enabled is the F401 production source patch. Other gate configurations are diagnostic controls.']}
out.write_text(json.dumps(cfg,indent=2));print(json.dumps({'phase':cfg['phase'],'gate':gate,'variants':cfg['variant_inits_decimal']}))
